class SavedCityFeet:
	# A saved foot needs the same final collision geometry as a playable city.
	# Keep one validation owner per destination for all of its remembered doors.
	var verified: Dictionary = {}

	func prepare_navigation(data: Dictionary, fallback: StringName, targets: Dictionary) -> Dictionary:
		if targets.is_empty():
			return LUOYANG_V3.prepare_navigation(data, fallback, targets)
		if not LUOYANG_V3.versions_supported(data, targets):
			return {}
		var versions: Dictionary = data.get("local_layout_versions", {}).duplicate()
		for id: String in targets:
			if int(versions.get(id, 1)) != LUOYANG_V3.VERSION or int(targets[id]) != LUOYANG_V3.VERSION:
				return LUOYANG_V3.prepare_navigation(data, fallback, targets)
		if LUOYANG_V3._live_source_token > 0 or not LUOYANG_V3._transition_validation.is_empty():
			return {}
		var result := data.duplicate(true)
		result.current_field = String(data.get("current_field", fallback))
		var returns: Dictionary = result.get("portal_return_spawns", {})
		for id: String in targets:
			var raw := ResourceLoader.load("res://data/scenes/%s.tres" % id, "", ResourceLoader.CACHE_MODE_IGNORE) as SceneScript
			var token := 0
			var ok := verified.has(id)
			if not ok:
				token = Time.get_ticks_usec() + 1
				ok = LUOYANG_V3.resolve_scene_for_transition(raw, token) != null
			if ok and id == result.current_field:
				var foot: Variant = repaired(id, LUOYANG_V3._vec(result.get("current_field_spawn")))
				ok = foot is Vector2
				if ok: result.current_field_spawn = [foot.x, foot.y]
			for key: String in returns:
				var parts := key.split("->")
				if not ok or parts.size() != 2 or parts[1] != id: continue
				var foot: Variant = repaired(id, LUOYANG_V3._vec(returns[key]))
				ok = foot is Vector2
				if ok: returns[key] = [foot.x, foot.y]
			if token > 0: LUOYANG_V3.end_transition_validation(token)
			if not ok: return {}
		result.portal_return_spawns = returns
		versions.merge(targets, true)
		result.local_layout_versions = versions
		return result

	func repaired(id: String, foot: Vector2) -> Variant:
		if verified.has(id): return verified[id].get(foot)
		return LUOYANG_V3.repair_spawn(StringName(id), foot)


func prepare_menu_save_feet(data: Dictionary) -> SavedCityFeet:
	var feet := SavedCityFeet.new()
	var versions: Variant = data.get("local_layout_versions", {})
	var returns: Variant = data.get("portal_return_spawns", {})
	if not versions is Dictionary or not returns is Dictionary: return null
	var points: Dictionary = {}
	var current := String(data.get("current_field", ""))
	if not current.is_empty(): points[current] = [data.get("current_field_spawn")]
	for key: Variant in returns:
		if not key is String: return null
		var parts := String(key).split("->")
		if parts.size() == 2:
			if not points.has(parts[1]): points[parts[1]] = []
			points[parts[1]].append(returns[key])
	for id: String in points.keys():
		if not LUOYANG_V3.owns_id(StringName(id)) or REGION27D.enabled(self, StringName(id)) or not LUOYANG_V3._num(versions.get(id, 1), LUOYANG_V3.VERSION):
			points.erase(id)
	if points.is_empty(): return feet
	if _city_transition_token != 0 or LUOYANG_V3._live_source_token != 0 or not LUOYANG_V3._transition_validation.is_empty(): return null
	var token := LoadingManager.begin_field_preparation("读取洛阳存档")
	if token <= 0: return null
	await get_tree().process_frame
	var ok := true
	for id: String in points:
		var raw := ResourceLoader.load(FIELD_SCENE_DIR + id + ".tres", "", ResourceLoader.CACHE_MODE_IGNORE) as SceneScript
		var previous_resident := LUOYANG_V3._resident_ready
		var stores := [LUOYANG_V3._records, LUOYANG_V3._masks, LUOYANG_V3._solids, LUOYANG_V3._using_patch]
		var previous: Array = []
		for values: Dictionary in stores: previous.append(values.get(id))
		var scene := await LUOYANG_V3.resolve_scene_for_live_transition(raw, token)
		ok = scene != null and await LUOYANG_V3.finalize_live_transition_sources(token, StringName(id))
		if ok:
			feet.verified[id] = {}
			for point: Variant in points[id]:
				var uv := LUOYANG_V3._vec(point)
				var repaired: Variant = LUOYANG_V3.repair_spawn(StringName(id), uv)
				if not repaired is Vector2:
					ok = false
					break
				feet.verified[id][uv] = repaired
		LUOYANG_V3.end_transition_validation(token)
		LUOYANG_V3._resident_ready = previous_resident
		for i: int in stores.size():
			if previous[i] == null: stores[i].erase(id)
			else: stores[i][id] = previous[i]
		if not ok: break
	LoadingManager.finish_field_preparation(token)
	return feet if ok else null

func _prepare_region27d_navigation(data: Dictionary,fallback: StringName, feet: SavedCityFeet = null) -> Dictionary:
	var versions: Variant = data.get("local_layout_versions", {})
	if not versions is Dictionary:
		return {}
	var city_data := data.duplicate(true)
	var city_versions: Dictionary = city_data.get("local_layout_versions", {})
	var other_versions: Dictionary = {}
	var referenced_fields: Dictionary = {String(data.get("current_field", fallback)): true}
	var returns: Variant = data.get("portal_return_spawns", {})
	if not returns is Dictionary:
		return {}
	for route: Variant in returns:
		var parts := String(route).split("->")
		if parts.size() == 2:
			referenced_fields[parts[1]] = true
	for id: Variant in versions:
		if not id is String:
			return {}
		var field_id := StringName(id)
		var version: Variant = versions[id]
		if typeof(version) not in [TYPE_INT, TYPE_FLOAT] or not is_finite(float(version)) or float(version) < 1 or float(version) > 2147483647.0 or floorf(float(version)) != float(version):
			push_warning("[SceneRouter] 无法识别存档中的场景坐标版本：" + id)
			return {}
		if REGION27D_ENABLED and REGION27D.enabled(self, field_id):
			continue
		if LUOYANG_V3.owns_id(field_id):
			if int(version) not in [1, LUOYANG_V3.VERSION]:
				return {}
			if referenced_fields.has(id):
				continue
		elif not field_id.is_valid_identifier() or not ResourceLoader.exists(field_scene_resource_path(field_id), "Resource"):
			push_warning("[SceneRouter] 无法识别存档中的场景坐标版本：" + id)
			return {}
		city_versions.erase(id)
		other_versions[id] = int(version)
	city_data.local_layout_versions = city_versions
	# City preflight owns only its own layout versions. Native towns restore theirs
	# from the same saved versions when the Router opens the selected field.
	var target_versions := _city_target_versions(referenced_fields)
	var prepared: Dictionary
	if REGION27D_ENABLED:
		prepared = REGION27D.preflight(self, city_data, fallback, target_versions, feet if feet != null else SavedCityFeet.new())
	else:
		prepared = LUOYANG_V3.prepare_navigation(city_data, fallback, target_versions)
	if not prepared.is_empty():
		prepared.local_layout_versions.merge(other_versions)
	return prepared

