	if _resident_parked: return # Detached live exterior; explicit discard owns cleanup.
	_release_world_v15_stream()
	if _current_scene!=null and LUOYANG_V3.owns_id(_current_scene.scene_id): LUOYANG_V3.clear_resident_receipt()
	_city3_motion_revision += 1
	_release_temple_session()
	_release_district_session()
	_release_city3_motion()
	_release_gate_moat_runtime()
	_release_city_building_fade()
	_release_world_travel_minimap()


func _gate_source_prewarm_after_first_draw() -> void:
	var helper: Variant = load("res://build/luoyang_loading_20261024e_perf01/candidate04/gate_source_prewarm04.gd")
	if not helper.enabled() or _current_scene == null: return
	var source_scene: SceneScript = _current_scene
	var revision: int = _city3_motion_revision
	while is_inside_tree() and get_tree().current_scene == self and _current_scene == source_scene and _city3_motion_revision == revision:
		await RenderingServer.frame_post_draw
		if not is_inside_tree() or get_tree().current_scene != self or _current_scene != source_scene or _city3_motion_revision != revision: return
		var loading: Node = get_node_or_null("/root/LoadingManager")
		var screen: Node = loading.get("_screen") if loading != null else null
		var hidden: bool = loading != null and loading.get("_transition_active") == false and loading.get("_external_active") == false and (screen == null or not bool(screen.call("is_showing")))
		if hidden and _field_loading_complete and not _scene_rebuilding and is_instance_valid(_player) and _player.can_process() and _player.can_move and is_instance_valid(_world_v15_stream) and _world_v15_stream.call("visual_ready_for_motion", world_container.to_local(_player.global_position)):
			# This is after an actual hidden operable World draw, never before ready.
			helper.start(self, source_scene, Time.get_ticks_usec(), Engine.get_process_frames())
			return


func resident_estimated_bytes() -> int:
	# Conservative texture RGBA estimate + mask/prefix. This is not a VRAM query.
	var seen: Dictionary={}
	var total:=3072*2048*8
	var pending: Array[Node]=[self]
	while not pending.is_empty():
		var node: Node=pending.pop_back()
		for child: Node in node.get_children(): pending.append(child)
		for property: Dictionary in node.get_property_list():
			if property.type!=TYPE_OBJECT: continue
			var value: Variant=node.get(property.name)
			if value is Texture2D and not seen.has(value.get_instance_id()):
				seen[value.get_instance_id()]=true
				total+=int(value.get_width())*int(value.get_height())*6
	return total

