func _setup_world_travel_minimap(scene: SceneScript) -> void:
	if not SceneRouter.is_world_map_scene(scene.scene_id):
		if not is_instance_valid(_primary_hud) or not CITY_LOCAL_MINIMAP.accepts(scene): return
		var local_map: Control = CITY_LOCAL_MINIMAP.new()
		local_map.name = "CityLocalMinimap"
		_primary_hud.add_child(local_map)
		if not local_map.call("configure", self, scene, _player, _world_camera, world_container):
			local_map.queue_free(); return
		_world_travel_minimap = local_map
		return
	if not SceneRouter.is_world_map_scene(scene.scene_id) or not is_instance_valid(_primary_hud):
		return
	var minimap: Control = WORLD_TRAVEL_MINIMAP.new()
	minimap.name = "WorldTravelMinimap"
	_primary_hud.add_child(minimap)
	if not minimap.call("configure", scene, _player, _world_camera, world_container):
		minimap.queue_free()
		return
	_world_travel_minimap = minimap


