# Exact original Family storage + the real finish Weak lease; setup only.
# This does not grant FINAL, change owner tokens or replace the original match.
func _finish25i_family_visual_setup_matches(family: Variant, kind: String) -> bool:
	if _current_scene == null or _current_scene.map_layout == null or _finish25i == null or not _scene_rebuilding or _field_loading_failed or not is_instance_valid(world_container) or not _finish25i._owned(true,true): return false
	if _finish25i.get_script() != _finish25i_script() or not family is GDScript: return false
	var expected_path: String = "res://scripts/city/luoyang_quarters_family_20261022ap.gd" if kind == "QUARTER_ORIGINAL" else ("res://scripts/city/luoyang_estate_family_20261021am.gd" if kind == "ESTATE_ORIGINAL" else "")
	if expected_path.is_empty() or family.resource_path != expected_path or not family.matches(_current_scene): return false
	var state: Dictionary = _finish25i.get("_state")
	if state.is_empty() or state.get("owner_kind") != kind or state.get("released",true) or not state.get("field") is WeakRef or state.field.get_ref() != self or not state.get("scene") is WeakRef or state.scene.get_ref() != _current_scene or not state.get("layout") is WeakRef or state.layout.get_ref() != _current_scene.map_layout: return false
	var original: Dictionary = family.original_receipt_for(_current_scene)
	if original.is_empty() or original.get("serial") != state.get("token") or original.get("key") != state.get("owner_key") or var_to_bytes(original.get("source_first")) != var_to_bytes(state.get("first")): return false
	if not state.get("first") is Dictionary or not state.first.has(expected_path) or not state.get("payload") is Dictionary: return false
	if state.get("binding_sha") != _finish25i.get_script().BIND_SHA or var_to_bytes(state.get("parent_blockers")) != var_to_bytes(_current_scene.map_layout.blockers) or var_to_bytes(state.payload.get("parent_native_navigation")) != var_to_bytes(_current_scene.map_layout.visual_objects): return false
	return true

# Only restore the original source-bound water visual skipped by finish bodies.
# Never call native_geometry.install or create a second set of original bodies.
func _finish25i_install_original_garden_water(collision_data: Array) -> bool:
	if _current_scene == null or _current_scene.scene_id != &"luoyang_riverside_garden_20261022ap": return false
	var family: Variant = load("res://scripts/city/luoyang_quarters_family_20261022ap.gd")
	if not _finish25i_family_visual_setup_matches(family,"QUARTER_ORIGINAL") or _world_size != Vector2(3072,2048) or not is_instance_valid(_visual_layer) or _visual_layer.get_parent() != world_container: return false
	if var_to_bytes(collision_data) != var_to_bytes(_current_scene.map_layout.blockers) or _visual_layer.get_node_or_null("APGardenSameCaptureWater") != null or _visual_layer.get_node_or_null("APGardenSameCaptureRiver25h") != null: return false
	var state: Dictionary = _finish25i.get("_state")
	var native_path: String = "res://scripts/city/luoyang_quarters_native_geometry_20261022ap.gd"
	var river_path: String = "res://build/luoyang_garden_river_20261025h_source01/garden_river_visual_NOTREADY.gd"
	for path: String in [native_path,river_path]:
		if not state.first.has(path) or FileAccess.get_sha256(path) != state.first[path]: return false
	var native_geometry: Variant = load(native_path)
	if not native_geometry is GDScript or native_geometry.resource_path != native_path or not native_geometry.can_instantiate() or not _current_scene.has_meta("ap_garden_river25h") or not family.garden_river_source_bound_scene(_current_scene): return false
	var checked: Dictionary = native_geometry.garden_water(self,_current_scene,collision_data,family)
	if checked.get("ok") != true: return false
	var water: Polygon2D = checked.get("node") as Polygon2D
	if not is_instance_valid(water): return false
	var receipt: Variant = water.get_meta("garden_river_visual_receipt",null)
	if water.get_parent() != null or water.name != &"APGardenSameCaptureRiver25h" or water.z_index != -18 or checked.get("river_visual_polygons") != 1 or checked.get("river_physical_water_pieces") != 2 or not receipt is Dictionary or receipt.get("shore_tiles",0) <= 0 or receipt.get("same_native_water_minus_deck_physics_and_mask") != true or not _finish25i._owned(true,true):
		water.free();return false
	_visual_layer.add_child(water)
	return water.get_parent() == _visual_layer

