	glow.texture = _make_radial_texture(256, color, Color(color.r, color.g, color.b, 0.0))
	glow.centered = true
	glow.scale = Vector2(size_px.x / 128.0, size_px.y / 128.0)
	glow.modulate.a = 0.45
	root.add_child(glow)
