	var room_services: Variant = ELEVEN_ROOMS
	if _current_scene != null and room_services.service_requested(_current_scene.scene_id):
		var projected_services: Dictionary = room_services.service_project_rows(_current_scene,npc_data,self)
		if projected_services.get("ok") != true:
			_field_loading_failed = true; push_error("[Field] Indoor service source/parent projection refused"); return
		npc_data = projected_services.npcs
		if _indoor_services != null: _indoor_services.abort("actors_rebuilt")
