		npc.dialog_id = String(d.get("dialog_id", ""))
		npc.interaction_action = String(d.get("interaction_action", ""))
		npc.dialog_variants.assign(d.get("dialog_variants", []))
		npc.portrait_path = String(d.get("portrait_path", ""))
