			const MONK_VISUAL_HELPER: String = "res://build/luoyang_city_finish_20261025i_source01/Estate_wall_source_repair01/closure_READY01/wing_door_depth_children_READY.gd"
			if FileAccess.get_sha256(MONK_VISUAL_HELPER) != "9116c468fb46feffd6625e5752d5c9c21cfb9662100787ae810d129d7c185d00":
				npc.free(); _field_loading_failed=true; push_error("[Field] Temple display source changed"); return
			var monk_visual: Variant=load(MONK_VISUAL_HELPER)
			var monk_projection: Dictionary=monk_visual.project_actor(self,d,npc)
			var old_elder_pending: bool=npc.npc_id=="temple_cave_keeper_20261018t" and monk_visual.ELDER_PAIR_ADOPTED==false and monk_projection.get("elder_pair_pending")==true
			if monk_projection.get("ok")!=true or (monk_projection.get("matched")!=true and not old_elder_pending):
				npc.free(); _field_loading_failed=true; push_error("[Field] Temple display parent/owner refused"); return
		_actor_layer.add_child(npc)
		if _v14_modular_overlap != null:
