		if member == null:
			continue
		member.hp = clampi(int(entry.get("hp", member.hp)), 1, member.max_hp)
		member.mp = clampi(int(entry.get("mp", member.mp)), 0, member.max_mp)
	player_changed.emit()
	party_changed.emit()


func reconcile_martial_transmissions() -> void:
	if player == null:
		return
	if bool(flags.get("joined_faction", false)):
		for starter: StringName in FACTION_SKILLS.get(String(player_faction), []):
			learn_skill(starter)
	# 只补这两次师门传艺，不重结旧任务或重复发放阅历、物品。
	for quest_id: StringName in [&"q_ch6_main_06_ancient_road_letter", &"q_ch7_main_11_disclosure_strategy"]:
		if QuestManager.is_completed(quest_id):
			var quest := QuestManager.load_def(quest_id)
			for reward: StringName in quest.reward_skills_by_faction.get(String(player_faction), []):
				learn_skill(reward)
	for known: StringName in player.skills.duplicate():
		var skill := _load_skill(known)
		if skill == null:
			continue
		if skill.breakthrough_quest != &"" and QuestManager.is_completed(skill.breakthrough_quest):
			_realize_quest_mastery(skill, false)
		if skill.mastery_unlock_skill != &"" and get_skill_mastery(known) >= skill.get_max_mastery():
			learn_skill(skill.mastery_unlock_skill)


