func _ready() -> void:
	_school_choice_menu = FORMAL_CHOICE_SCENE.instantiate() as FormalChoiceMenu
	_school_choice_menu.name = "SchoolChoiceMenu"
	_school_choice_menu.item_selected.connect(_set_school_filter)
	add_child(_school_choice_menu)
	if not EventBus.skill_learned.is_connected(_on_runtime_skill_learned):
		EventBus.skill_learned.connect(_on_runtime_skill_learned)
	if not EventBus.training_points_changed.is_connected(_on_training_points_changed):
		EventBus.training_points_changed.connect(_on_training_points_changed)
	if not EventBus.equipment_changed.is_connected(_on_equipment_changed):
		EventBus.equipment_changed.connect(_on_equipment_changed)
	if ResourceLoader.exists(ATTR_ICON_ATLAS_PATH):
		_attr_icon_atlas = load(ATTR_ICON_ATLAS_PATH)
	_load_skills()
	_setup_runtime_v2()
	_refresh_runtime_v2()


func open() -> void:
	visible = true
	_load_skills()
	_refresh_runtime_v2()


func _on_runtime_skill_learned(_skill_id: StringName, _display_name: String) -> void:
	_load_skills()
	if visible:
		_refresh_runtime_v2()


func _on_training_points_changed(_total: int, _available: int) -> void:
	if visible:
		_refresh_runtime_v2()


func _on_equipment_changed(_slot: int, _item_id: StringName) -> void:
	if visible:
		_refresh_runtime_v2()


func close() -> void:
	visible = false
	emit_signal("closed")


func _build_formal_layout() -> void:
	var body: VBoxContainer = get_node_or_null("Panel/Body") as VBoxContainer
	if body == null:
		return

	var toolbar: HBoxContainer = body.get_node_or_null("SkillToolbar") as HBoxContainer
	if toolbar != null:
		body.move_child(toolbar, 1)
		_apply_toolbar_style(toolbar)
	else:
		_build_toolbar_in_code(body)

	var content: HBoxContainer = get_node_or_null("Panel/Body/Content") as HBoxContainer
	if content != null:
		content.add_theme_constant_override("separation", 18)
	var list_scroll: ScrollContainer = get_node_or_null("Panel/Body/Content/ListScroll") as ScrollContainer
	if list_scroll != null:
		list_scroll.custom_minimum_size = Vector2(430, 0)
	detail.custom_minimum_size = Vector2(610, 0)
	detail.size_flags_horizontal = Control.SIZE_EXPAND_FILL

	var actions: HBoxContainer = body.get_node_or_null("SkillActions") as HBoxContainer
	if actions != null:
		if _quick_btn == null:
			_quick_btn = actions.get_node_or_null("QuickBtn") as Button
			if _quick_btn != null:
				_apply_btn_textures(_quick_btn, "btn_quick")
				_quick_btn.pressed.connect(_set_quick_skill)
		if _practice_btn == null:
			_practice_btn = actions.get_node_or_null("PracticeBtn") as Button
			if _practice_btn != null:
				_apply_btn_textures(_practice_btn, "btn_practice")
				_practice_btn.pressed.connect(_practice_selected)
	else:
		_build_actions_in_code(body)


func _apply_toolbar_style(toolbar: HBoxContainer) -> void:
	_attach_filter_button(toolbar, "BtnAll", "all", "全部")
	_attach_filter_button(toolbar, "BtnAttack", "attack", "攻击")
	_attach_filter_button(toolbar, "BtnSupport", "support", "辅助")
	_attach_filter_button(toolbar, "BtnDefense", "defense", "防御")

	if _school_filter_button == null:
		var insert_index := maxi(0, toolbar.get_child_count() - 1)
		_school_filter_button = Button.new()
		_school_filter_button.name = "SchoolFilterButton"
		_school_filter_button.custom_minimum_size = Vector2(150, 36)
		_school_filter_button.text = "全部流派"
		_school_filter_button.tooltip_text = "筛选流派"
		toolbar.add_child(_school_filter_button)
		toolbar.move_child(_school_filter_button, insert_index)
		_apply_btn_textures(_school_filter_button, "tab")
		_school_filter_button.pressed.connect(_open_school_choice_menu)

	_summary_label = toolbar.get_node_or_null("Summary") as Label
	if _summary_label != null:
		UI_THEME.style_label(_summary_label, 16, UI_THEME.MUTED, false)

	_update_filter_highlights()


func _open_school_choice_menu() -> void:
	if _school_choice_menu == null:
		return
	var names := {
		"all": "全部流派", "linxi": "林西", "gufeng": "孤峰", "huashan": "华山",
		"lingyue": "凌月", "mingwu": "茗雾", "wudang": "武当", "generic": "通用",
	}
	var options: Array[Dictionary] = []
	for school: String in ["all", "linxi", "gufeng", "huashan", "lingyue", "mingwu", "wudang", "generic"]:
		options.append({"id": StringName(school), "label": names[school]})
	_school_choice_menu.show_choices("选择流派", options, StringName(_school_filter))


func _set_school_filter(school_id: StringName) -> void:
	_school_filter = String(school_id)
	var names := {
		"all": "全部流派", "linxi": "林西", "gufeng": "孤峰", "huashan": "华山",
		"lingyue": "凌月", "mingwu": "茗雾", "wudang": "武当", "generic": "通用",
	}
	if _school_filter_button != null:
		_set_button_caption(_school_filter_button, names.get(_school_filter, "全部流派"))
	_refresh_list()


func _update_filter_highlights() -> void:
	var toolbar: HBoxContainer = get_node_or_null("Panel/Body/SkillToolbar") as HBoxContainer
	if toolbar == null: return
	var mode_map := {"BtnAll": "all", "BtnAttack": "attack", "BtnSupport": "support", "BtnDefense": "defense"}
	for btn_name in mode_map:
		var btn: Button = toolbar.get_node_or_null(str(btn_name)) as Button
		if btn == null: continue
		var is_sel: bool = _filter_mode == str(mode_map[btn_name])
		var tex: Texture2D = _try_load("tab_selected.png" if is_sel else "tab_normal.png")
		if tex != null:
			btn.add_theme_stylebox_override("normal", _tex_stylebox(tex))


func _build_toolbar_in_code(body: VBoxContainer) -> void:
	var toolbar: HBoxContainer = HBoxContainer.new()
	toolbar.name = "SkillToolbar"
	toolbar.add_theme_constant_override("separation", 10)
	body.add_child(toolbar)
	body.move_child(toolbar, 1)
	_add_filter_button(toolbar, "全部", "all")
	_add_filter_button(toolbar, "攻击", "attack")
	_add_filter_button(toolbar, "辅助", "support")
	_add_filter_button(toolbar, "防御", "defense")
	_summary_label = Label.new()
	_summary_label.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_summary_label.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
	UI_THEME.style_label(_summary_label, 16, UI_THEME.MUTED, false)
	toolbar.add_child(_summary_label)


func _build_actions_in_code(body: VBoxContainer) -> void:
	var actions: HBoxContainer = HBoxContainer.new()
	actions.name = "SkillActions"
	actions.alignment = BoxContainer.ALIGNMENT_CENTER
	actions.add_theme_constant_override("separation", 12)
	body.add_child(actions)
	_quick_btn = Button.new()
	_quick_btn.text = "设为快捷招式"
	_quick_btn.custom_minimum_size = Vector2(170, 42)
	UI_THEME.style_button(_quick_btn, 16, UI_THEME.JADE)
	_quick_btn.pressed.connect(_set_quick_skill)
	actions.add_child(_quick_btn)
	_practice_btn = Button.new()
	_practice_btn.text = "研读招式"
	_practice_btn.custom_minimum_size = Vector2(140, 42)
	UI_THEME.style_button(_practice_btn, 16, UI_THEME.BLUE_STEEL)
	_practice_btn.pressed.connect(_practice_selected)
	actions.add_child(_practice_btn)


func _add_filter_button(parent: HBoxContainer, label: String, mode: String) -> void:
	var btn: Button = Button.new()
	btn.text = label
	btn.custom_minimum_size = Vector2(96, 38)
	UI_THEME.style_button(btn, 15, UI_THEME.BLUE_STEEL)
	btn.pressed.connect(func(): _set_filter(mode))
	parent.add_child(btn)


func _attach_filter_button(toolbar: HBoxContainer, node_name: String, mode: String, label: String) -> void:
	var btn: Button = toolbar.get_node_or_null(node_name) as Button
	if btn == null:
		_add_filter_button(toolbar, label, mode)
		return
	_apply_btn_textures(btn, "tab")
	btn.tooltip_text = label
	var lbl := btn.get_child(btn.get_child_count() - 1) as Label
	if lbl != null: lbl.text = label
	btn.pressed.connect(func(): _set_filter(mode))


func _set_filter(mode: String) -> void:
	_filter_mode = mode
	_update_filter_highlights()
	_refresh_list()


func _apply_visual_style() -> void:
	var dim: ColorRect = get_node_or_null("Dim") as ColorRect
	if dim != null:
		# Keep the field readable around the generated panel; the old heavy veil
		# made the narrow outer area read as an extra black border.
		dim.color = Color(0.005, 0.010, 0.016, 0.34)
	var panel: PanelContainer = get_node_or_null("Panel") as PanelContainer
	if panel != null:
		# Keep the interactive layout inside the plain 1280x720 frame.  The
		# former full-page concept art had baked scenery outside this safe area.
		panel.offset_left = -640
		panel.offset_top = -360
		panel.offset_right = 640
		panel.offset_bottom = 360
		var panel_style: StyleBoxEmpty = StyleBoxEmpty.new()
		panel_style.content_margin_left = 72.0
		panel_style.content_margin_top = 74.0
		panel_style.content_margin_right = 72.0
		panel_style.content_margin_bottom = 54.0
		panel.add_theme_stylebox_override("panel", panel_style)
	var title: Label = get_node_or_null("Panel/Body/Header/Title") as Label
	if title != null:
		title.text = "武学"
		UI_THEME.style_label(title, 34, UI_THEME.GOLD_LIGHT)

	var cn: Texture2D = _try_load("btn_close_normal.png")
	if cn != null:
		close_btn.flat = true
		close_btn.text = "关闭"
		close_btn.custom_minimum_size = Vector2(cn.get_width(), cn.get_height())
		close_btn.add_theme_font_size_override("font_size", 16)
		close_btn.add_theme_color_override("font_color", Color(0.86, 0.93, 0.95, 1.0))
		close_btn.add_theme_color_override("font_hover_color", Color(1.0, 0.92, 0.62, 1.0))
		close_btn.add_theme_stylebox_override("normal", _tex_stylebox(cn))
		close_btn.add_theme_stylebox_override("hover", _tex_stylebox(_try_load("btn_close_hover.png")))
		close_btn.add_theme_stylebox_override("pressed", _tex_stylebox(_try_load("btn_close_pressed.png")))
	else:
		UI_THEME.style_button(close_btn, 16, UI_THEME.CRIMSON)

	detail.add_theme_font_size_override("normal_font_size", 18)
	detail.add_theme_color_override("default_color", Color(0.84, 0.91, 0.93, 1.0))
	detail.add_theme_stylebox_override("normal", StyleBoxEmpty.new())


func _load_skills() -> void:
	_skills.clear()
	if GameState.player == null:
		return
	var learned_ids: Dictionary = {}
	for skill_id in GameState.player.skills:
		learned_ids[skill_id] = true
	var dir: DirAccess = DirAccess.open(SKILL_DIR)
	if dir == null:
		push_warning("[SkillPanel] skill dir missing: %s" % SKILL_DIR)
		return
	var files: PackedStringArray = dir.get_files()
	files.sort()
	for file_name in files:
		if not file_name.ends_with(".tres"):
			continue
		var res: Resource = load(SKILL_DIR + file_name)
		if res is Skill:
			var skill: Skill = res
			if learned_ids.has(skill.skill_id):
				_skills.append(skill)


func _refresh_list() -> void:
	for child in skill_list.get_children():
		child.queue_free()
	var visible_skills: Array[Skill] = []
	for skill in _skills:
		if not _skill_visible(skill):
			continue
		visible_skills.append(skill)
		skill_list.add_child(_make_skill_row(skill))
	_update_summary()
	if visible_skills.is_empty():
		_show_empty()
		return
	if _selected_skill_id == &"" or _find_skill(_selected_skill_id) == null:
		_selected_skill_id = visible_skills[0].skill_id
	_show_selected()


func _skill_visible(skill: Skill) -> bool:
	if _school_filter != "all" and skill.school != _school_filter:
		return false
	match _filter_mode:
		"attack":
			return skill.kind == Skill.Kind.ATTACK and not _is_defense_skill(skill)
		"support":
			return skill.kind != Skill.Kind.ATTACK and not _is_defense_skill(skill)
		"defense":
			return _is_defense_skill(skill)
		_:
			return true


func _make_skill_row(skill: Skill) -> Control:
	var row_panel: PanelContainer = PanelContainer.new()
	row_panel.custom_minimum_size = Vector2(0, 96)
	var row_tex: Texture2D = _try_load("skill_row_selected.png" if skill.skill_id == _selected_skill_id else "skill_row_normal.png")
	if row_tex != null:
		row_panel.add_theme_stylebox_override("panel", _tex_stylebox(row_tex))
	else:
		var border := _kind_accent(skill)
		if skill.skill_id == _selected_skill_id:
			border = UI_THEME.GOLD_LIGHT
		row_panel.add_theme_stylebox_override("panel", UI_THEME.panel(Color(0.038, 0.060, 0.072, 0.90), border, 12, 1))
	var row: HBoxContainer = HBoxContainer.new()
	row.add_theme_constant_override("separation", 10)
	row_panel.add_child(row)
	var icon := _make_skill_icon(skill)
	if icon != null:
		row.add_child(icon)
	var btn: Button = Button.new()
	var mastery := GameState.get_skill_mastery(skill.skill_id)
	var total_scaling := _skill_attack_scaling(skill, mastery)
	var atk := _player_effective_attack(skill)
	if _uses_damage_formula(skill):
		var damage_range := BattleFormula.estimate_damage_range(atk, skill.fixed_damage, total_scaling)
		btn.text = "%s  ·  %s\n⚔ %d-%d  · 固定%d + 攻击×%d%%" % [
			skill.display_name, _kind_text(skill.kind),
			damage_range.x, damage_range.y, skill.fixed_damage, total_scaling,
		]
	elif skill.kind == Skill.Kind.HEAL:
		btn.text = "%s  ·  治疗\n♥ 恢复约 %d  · 固定%d + 内劲×4" % [
			skill.display_name, _skill_effect_preview(skill), skill.get_effect_value(),
		]
	else:
		btn.text = "%s  ·  %s\n◆ %s" % [
			skill.display_name, _kind_text(skill.kind), _non_damage_effect_text(skill),
		]
	btn.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	btn.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	btn.custom_minimum_size = Vector2(0, 74)
	UI_THEME.style_button(btn, 16, _kind_accent(skill))
	var quality_color := QUALITY_COLORS[clampi(skill.quality, 0, QUALITY_COLORS.size() - 1)]
	btn.add_theme_color_override("font_color", quality_color)
	btn.add_theme_color_override("font_hover_color", quality_color.lightened(0.16))
	var captured_id: StringName = skill.skill_id
	btn.pressed.connect(func(): _select_skill(captured_id))
	row.add_child(btn)
	return row_panel


func _select_skill(skill_id: StringName) -> void:
	_selected_skill_id = skill_id
	_refresh_list()


func _show_selected() -> void:
	var skill := _find_skill(_selected_skill_id)
	if skill == null:
		_show_empty()
		return
	_show_skill(skill)


func _show_empty() -> void:
	detail.text = "武学\n\n当前分类下暂无招式。"
	if _quick_btn != null:
		_quick_btn.disabled = true
	if _practice_btn != null:
		_practice_btn.disabled = true


func _show_skill(skill: Skill) -> void:
	var mastery := GameState.get_skill_mastery(skill.skill_id)
	var is_mind := _runtime_is_mind(skill)
	var total_scaling := _skill_attack_scaling(skill, mastery)
	var atk := _player_effective_attack(skill)
	var combat_line := ""
	if _uses_damage_formula(skill):
		var damage_range := BattleFormula.estimate_damage_range(atk, skill.fixed_damage, total_scaling)
		combat_line = "[color=#ffb14a]伤害：%d - %d[/color]（固定 %d + 当前攻击力 %d × %d%%）" % [damage_range.x, damage_range.y, skill.fixed_damage, atk, total_scaling]
	elif skill.kind == Skill.Kind.HEAL:
		combat_line = "[color=#72d2a6]治疗：约 %d[/color]（固定 %d + 当前内劲 %d × 4）" % [_skill_effect_preview(skill), skill.get_effect_value(), _player_inner_power()]
	else:
		combat_line = "[color=#9fd3d0]效果：%s[/color]" % _non_damage_effect_text(skill)

	if _quick_btn != null:
		_quick_btn.disabled = false
		if skill.skill_id == _quick_skill_id:
			_set_button_caption(_quick_btn, "已设为快捷")
		else:
			_set_button_caption(_quick_btn, "设为快捷招式")
	if _practice_btn != null:
		var required := skill.get_required_insight()
		var cost := GameState.get_skill_practice_cost(skill.skill_id)
		var insight_ok := GameState.get_effective_insight() >= required
		var self_cap := skill.get_self_practice_max_mastery()
		_practice_btn.disabled = mastery >= self_cap or not insight_ok or GameState.training_points_available < cost
		_set_button_caption(_practice_btn, "等待师门突破" if mastery >= self_cap and self_cap < skill.get_max_mastery() else ("研读完成" if mastery >= self_cap else "研读%s · %d 阅历" % ["心法" if is_mind else "招式", cost]))
	var quality_hex := QUALITY_COLORS[clampi(skill.quality, 0, QUALITY_COLORS.size() - 1)].to_html(false)
	if is_mind:
		detail.text = "[color=#%s]%s[/color]\n[color=#9fd3d0]心法 · 境界 %d/%d[/color]\n悟性要求：%d（当前 %d） · 下次研读：%s\n\n常驻功效\n%s\n\n主动运功\n%s\n\n心法说明\n%s" % [
			quality_hex,
			skill.display_name,
			skill.get_display_level(mastery),
			skill.max_level,
			skill.get_required_insight(),
			GameState.get_effective_insight(),
			"等待师门突破" if mastery >= skill.get_self_practice_max_mastery() and skill.self_practice_level_cap < skill.max_level else ("已完成" if mastery >= skill.get_self_practice_max_mastery() else "%d 阅历" % GameState.get_skill_practice_cost(skill.skill_id)),
			_passive_effect_text(skill, mastery),
			_active_effect_text(skill, mastery),
			skill.description,
		]
		return
	detail.text = "[color=#%s]%s[/color]\n[color=#9fd3d0]%s · %s · 境界 %d/%d[/color]\n悟性要求：%d（当前 %d） · 下次研读：%s\n\n战斗参数\n%s\n目标：%s\n内力消耗：%d\n攻击段数：%d\n动画：%s\n\n招式说明\n%s\n\n使用建议\n%s" % [
		quality_hex,
		skill.display_name,
		_kind_text(skill.kind),
		_quick_text(skill),
		skill.get_display_level(mastery),
		skill.max_level,
		skill.get_required_insight(),
		GameState.get_effective_insight(),
		"等待师门突破" if mastery >= skill.get_self_practice_max_mastery() and skill.self_practice_level_cap < skill.max_level else ("已完成" if mastery >= skill.get_self_practice_max_mastery() else "%d 阅历" % GameState.get_skill_practice_cost(skill.skill_id)),
		combat_line,
		_target_text(skill.target),
		skill.mp_cost,
		skill.hit_count,
		String(skill.animation_id),
		skill.description,
		_advice_text(skill),
	]


func _find_skill(skill_id: StringName) -> Skill:
	for skill in _skills:
		if skill.skill_id == skill_id:
			return skill
	return null


func _player_effective_attack(skill: Skill = null) -> int:
	var p: CharacterStats = GameState.player
	if p == null: return 10
	var final_attack_bonus := Inventory.get_atk_bonus()
	if skill != null and skill.damage_type == Skill.DamageType.INTERNAL:
		return BattleFormula.calc_internal_attack(p.inner_power, Inventory.get_inner_power_bonus(), final_attack_bonus)
	return BattleFormula.calc_external_attack(p.strength, Inventory.get_strength_bonus(), final_attack_bonus)


func _skill_attack_scaling(skill: Skill, mastery: int = -1) -> int:
	if mastery < 0:
		mastery = GameState.get_skill_mastery(skill.skill_id)
	var total := skill.get_attack_scaling() + mastery * 2
	var gear_bonus := Inventory.get_equipped_skill_bonus(skill.school, skill.get_bonus_weapon_style())
	total += int(gear_bonus.get("scaling", 0))
	var player: CharacterStats = GameState.player
	if player != null and skill.complemented_by != "" and player.equipped_internal_art == StringName(skill.complemented_by):
		total += skill.get_complement_scaling_bonus()
	if player != null:
		total += int(GameState.get_equipped_internal_art_bonus(player, skill).get("scaling", 0))
	return total


func _equipped_effect_text(skill: Skill, mastery: int) -> String:
	var lines := skill.get_equipped_effect_lines(mastery)
	return "无额外装备加成" if lines.is_empty() else "\n".join(lines)


func _uses_damage_formula(skill: Skill) -> bool:
	return skill.kind == Skill.Kind.ATTACK or skill.kind == Skill.Kind.DEBUFF


func _player_inner_power() -> int:
	var player: CharacterStats = GameState.player
	return player.inner_power + Inventory.get_inner_power_bonus() if player != null else 0


func _skill_effect_preview(skill: Skill, mastery: int = -1) -> int:
	if mastery < 0:
		mastery = GameState.get_skill_mastery(skill.skill_id)
	return maxi(0, skill.get_active_effect_value(mastery) + _player_inner_power() * 4)


func _non_damage_effect_text(skill: Skill) -> String:
	if skill.get_effect_value() > 0:
		return "固定效果 %d，并附加状态" % skill.get_effect_value()
	return "状态/被动效果（详见招式说明）"


func _passive_effect_text(skill: Skill, mastery: int) -> String:
	var lines := skill.get_passive_effect_lines(mastery)
	if lines.is_empty():
		return "无常驻属性加成"
	return "\n".join(lines)


func _active_effect_text(skill: Skill, mastery: int, next_mastery: int = -1, preview_hex: String = "") -> String:
	if not skill.has_active_effect():
		return "无主动运功（不会出现在战斗招式中）"
	var text := skill.active_effect_description.strip_edges()
	if text.is_empty():
		text = _non_damage_effect_text(skill)
	var active_value := skill.get_active_effect_value(mastery)
	var next_value := skill.get_active_effect_value(next_mastery) if next_mastery >= 0 else active_value
	if maxi(active_value, next_value) > 0 and (skill.kind == Skill.Kind.HEAL or skill.active_effect_type == &"heal_guard"):
		text += "\n恢复生命：%d + 内劲 × 4" % active_value
		text += _next_stat_suffix("%d + 内劲 × 4" % active_value, "%d + 内劲 × 4" % next_value, preview_hex)
	elif maxi(active_value, next_value) > 0 and skill.active_effect_type == &"redirect":
		text += "\n化解并返还：%d%%" % active_value
		text += _next_stat_suffix("%d%%" % active_value, "%d%%" % next_value, preview_hex)
	elif maxi(active_value, next_value) > 0:
		text += "\n效果数值：%d" % active_value
		text += _next_stat_suffix(str(active_value), str(next_value), preview_hex)
	var duration := skill.get_active_duration(mastery)
	var next_duration := skill.get_active_duration(next_mastery) if next_mastery >= 0 else duration
	if maxi(duration, next_duration) > 0:
		text += "\n持续：%d 回合" % duration
		text += _next_stat_suffix("%d 回合" % duration, "%d 回合" % next_duration, preview_hex)
	text += "\n内力消耗：%d" % skill.mp_cost
	return text


func _next_stat_suffix(current: String, next: String, hex: String) -> String:
	if hex.is_empty() or current == next:
		return ""
	return "  [color=#%s]→ %s[/color]" % [hex, next]


func _split_progress_stat(line: String) -> PackedStringArray:
	return line.split("：" if line.contains("：") else " ", true, 1)


func _preview_stat_lines(current: PackedStringArray, following: PackedStringArray, empty_text: String, hex: String) -> String:
	var next_by_name := {}
	for line in following:
		var parts := _split_progress_stat(line)
		if parts.size() == 2:
			next_by_name[parts[0]] = parts[1]
	var result := PackedStringArray()
	for line in current:
		var parts := _split_progress_stat(line)
		if parts.size() == 2 and not hex.is_empty():
			var next: String = next_by_name.get(parts[0], "无")
			line += _next_stat_suffix(parts[1], next, hex)
			next_by_name.erase(parts[0])
		result.append(line)
	if not hex.is_empty():
		for label: String in next_by_name:
			result.append("%s%s" % [label, _next_stat_suffix("", next_by_name[label], hex)])
	return empty_text if result.is_empty() else "\n".join(result)


func _set_quick_skill() -> void:
	if _selected_skill_id == &"":
		return
	_quick_skill_id = _selected_skill_id
	_show_selected()


func _practice_selected() -> void:
	var skill := _find_skill(_selected_skill_id)
	if skill == null:
		return
	if GameState.practice_skill(skill.skill_id):
		_show_selected()
	else:
		var required := skill.get_required_insight()
		if GameState.get_effective_insight() < required:
			detail.text += "\n\n[color=#e6a14f]悟性不足，需要 %d 点悟性。[/color]" % required
		elif GameState.get_skill_mastery(skill.skill_id) >= skill.get_self_practice_max_mastery():
			detail.text += "\n\n[color=#9fd3d0]这门招式已经研读至当前上限。[/color]"
		else:
			detail.text += "\n\n[color=#e6a14f]阅历不足，还需 %d 点。[/color]" % GameState.get_skill_practice_cost(skill.skill_id)


func _update_summary() -> void:
	if _summary_label == null:
		return
	var attack_count := 0
	var support_count := 0
	var defense_count := 0
	for skill in _skills:
		if _is_defense_skill(skill):
			defense_count += 1
		elif skill.kind == Skill.Kind.ATTACK:
			attack_count += 1
		else:
			support_count += 1
	_summary_label.text = "招式 %d · 攻击 %d · 辅助 %d · 防御 %d" % [_skills.size(), attack_count, support_count, defense_count]


func _is_defense_skill(skill: Skill) -> bool:
	var id_text := String(skill.skill_id).to_lower()
	var name_text := skill.display_name.to_lower()
	var desc_text := skill.description.to_lower()
	return id_text.contains("defend") or name_text.contains("防") or desc_text.contains("防") or desc_text.contains("守")


func _kind_accent(skill: Skill) -> Color:
	if _is_defense_skill(skill):
		return UI_THEME.BLUE_STEEL
	match skill.kind:
		Skill.Kind.ATTACK:
			return UI_THEME.JADE
		Skill.Kind.HEAL:
			return UI_THEME.GOLD
		Skill.Kind.BUFF:
			return UI_THEME.BLUE_STEEL
		Skill.Kind.DEBUFF:
			return UI_THEME.CRIMSON
		_:
			return UI_THEME.GOLD


func _quick_text(skill: Skill) -> String:
	return "快捷招式" if skill.skill_id == _quick_skill_id else "已掌握"


func _advice_text(skill: Skill) -> String:
	if _is_defense_skill(skill):
		return "适合在强敌蓄势或气血较低时使用，稳住战线。"
	if skill.kind == Skill.Kind.ATTACK and skill.mp_cost > 0:
		return "适合在内力充足时打出爆发，优先用于关键敌人。"
	if skill.kind == Skill.Kind.ATTACK:
		return "消耗低，可作为常规试探招式。"
	if skill.kind == Skill.Kind.HEAL:
		return "适合在气血告急时保命。"
	if skill.kind == Skill.Kind.DEBUFF:
		return "适合先手削弱敌人，为后续爆发创造机会。"
	return "适合根据战局灵活使用。"


func _kind_text(kind: int) -> String:
	match kind:
		Skill.Kind.ATTACK:
			return "攻击"
		Skill.Kind.HEAL:
			return "疗伤"
		Skill.Kind.BUFF:
			return "增益"
		Skill.Kind.DEBUFF:
			return "削弱"
		_:
			return "未知"


func _target_text(target: int) -> String:
	match target:
		Skill.Target.ENEMY_SINGLE:
			return "敌方单体"
		Skill.Target.ENEMY_ALL:
			return "敌方全体"
		Skill.Target.ALLY_SINGLE:
			return "己方单体"
		Skill.Target.ALLY_ALL:
			return "己方全体"
		Skill.Target.SELF:
			return "自身"
		_:
			return "未知"


func _make_skill_icon(skill: Skill) -> TextureRect:
	var tex: Texture2D = null
	var resolved_icon_path := _resolved_skill_icon_path(skill)
	if not resolved_icon_path.is_empty() and ResourceLoader.exists(resolved_icon_path):
		tex = load(resolved_icon_path)
	elif _attr_icon_atlas != null:
		var icon_key := "内劲"
		if _is_defense_skill(skill):
			icon_key = "防御"
		elif skill.kind == Skill.Kind.HEAL or skill.kind == Skill.Kind.BUFF:
			icon_key = "悟性"
		elif skill.kind == Skill.Kind.DEBUFF:
			icon_key = "机敏"
		var region: Rect2 = ATTR_ICON_REGIONS.get(icon_key, Rect2())
		if region.size.x > 0 and region.size.y > 0:
			var atlas_tex: AtlasTexture = AtlasTexture.new()
			atlas_tex.atlas = _attr_icon_atlas
			atlas_tex.region = region
			tex = atlas_tex
	if tex == null:
		return null
	var icon: TextureRect = TextureRect.new()
	icon.custom_minimum_size = Vector2(52, 52)
	icon.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
	icon.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
	icon.texture = tex
	return icon


func _try_load(name: String) -> Texture2D:
	var path: String = "res://art/ui/skill/" + name
	if ResourceLoader.exists(path): return load(path)
	return null


func _runtime_texture(name: String) -> Texture2D:
	var path: String = name if name.begins_with("res://") else "res://art/ui/skill/runtime_v2/" + name
	if ResourceLoader.exists(path):
		return load(path)
	return null


func _runtime_stylebox(texture: Texture2D, left: float = 0.0) -> StyleBoxTexture:
	var style := StyleBoxTexture.new()
	style.texture = texture
	style.content_margin_left = left
	style.content_margin_right = 8.0
	style.content_margin_top = 5.0
	style.content_margin_bottom = 5.0
